#!/usr/bin/env bash
# Validates a commit message against Conventional Commits
# (https://www.conventionalcommits.org), so history can drive
# automated release notes later.
#
# Usage: lint-commit-msg.sh <path-to-commit-msg-file>

set -euo pipefail

msg_file="$1"
# First non-comment, non-empty line is the header.
header=$(grep -vE '^\s*#' "$msg_file" | grep -vE '^\s*$' | head -n1 || true)

if [ -z "$header" ]; then
  echo "error: empty commit message" >&2
  exit 1
fi

# Allow merge commits and reverts generated by git itself.
if [[ "$header" =~ ^Merge\  ]]; then
  exit 0
fi

types="feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert"
pattern="^(${types})(\([a-z0-9.-]+\))?(!)?: [a-z0-9].{1,88}$"

if [[ ${#header} -gt 100 ]]; then
  echo "error: commit header too long (${#header} > 100 chars)" >&2
  echo "  $header" >&2
  exit 1
fi

if [[ "$header" =~ \.$ ]]; then
  echo "error: commit header must not end with a period" >&2
  echo "  $header" >&2
  exit 1
fi

if ! [[ "$header" =~ $pattern ]]; then
  cat >&2 <<EOF
error: commit header does not follow Conventional Commits

  $header

Expected format:
  <type>(<optional scope>): <description>

Valid types: feat, fix, docs, style, refactor, perf, test, build, ci, chore, revert
Description: lowercase start, imperative mood, no trailing period

Examples:
  feat(conveyor): add belt splitter component
  fix(sim): correct tick order for fluid mixing
  docs: note tech stack decision in CLAUDE.md

Breaking change: append "!" after the type/scope, e.g. feat!: ...
and add a "BREAKING CHANGE: ..." paragraph in the body.
EOF
  exit 1
fi

exit 0
